def parser(log: str) -> dict[str, str]:
    import re
    import html
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def status_from(outcome: str | None) -> str | None:
        if not outcome:
            return None
        o = outcome.strip().lower()
        if o in {"passed", "pass", "success"}:
            return "pass"
        if o in {"failed", "fail", "error", "timeout", "aborted", "crashed"}:
            return "fail"
        if o in {"skipped", "skip", "notexecuted", "inconclusive", "notrunnable", "disabled", "ignored"}:
            return "skip"
        return None

    def add_result(name: str | None, outcome: str | None):
        if not name:
            return
        status = status_from(outcome)
        if not status:
            return
        results[html.unescape(name)] = status

    def parse_trx(xml_text: str):
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return
        # Map testId -> name from UnitTest definitions
        id_to_name = {}
        for elem in root.iter():
            if elem.tag.endswith("UnitTest"):
                test_id = elem.get("id") or elem.get("testId") or elem.get("testid")
                name = elem.get("name") or elem.get("testName")
                if test_id and name:
                    id_to_name[test_id] = name
        for elem in root.iter():
            if elem.tag.endswith("UnitTestResult"):
                name = elem.get("testName")
                if not name:
                    test_id = elem.get("testId") or elem.get("testid")
                    name = id_to_name.get(test_id)
                outcome = elem.get("outcome") or elem.get("Outcome")
                add_result(name, outcome)

    def parse_junit(xml_text: str):
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return
        root_tag = root.tag.lower()
        if not root_tag.endswith("testsuite") and not root_tag.endswith("testsuites"):
            return
        for testcase in root.iter():
            if not testcase.tag.lower().endswith("testcase"):
                continue
            name = testcase.get("name")
            classname = testcase.get("classname")
            full_name = f"{classname}.{name}" if classname else name
            outcome = "passed"
            for child in testcase:
                tag = child.tag.lower()
                if tag.endswith("failure") or tag.endswith("error"):
                    outcome = "failed"
                    break
                if tag.endswith("skipped"):
                    outcome = "skipped"
                    break
            add_result(full_name, outcome)

    # Try parsing any TestRun blocks first
    for xml_block in re.findall(r"<TestRun\b.*?</TestRun>", log, re.DOTALL):
        parse_trx(xml_block)

    # If no TestRun blocks found, attempt to parse whole log as XML
    if not results:
        # Try TRX or JUnit in whole log
        trimmed = log.strip()
        if trimmed.startswith("\ufeff"):
            trimmed = trimmed.lstrip("\ufeff")
        parse_trx(trimmed)
        if not results:
            parse_junit(trimmed)

    # Fallback: regex parse UnitTestResult tags for outcomes
    if not results:
        for tag in re.findall(r"<UnitTestResult\b[^>]*>", log):
            attrs = dict(re.findall(r'(\w+)\s*=\s*"([^"]*)"', tag))
            name = attrs.get("testName") or attrs.get("testname")
            outcome = attrs.get("outcome") or attrs.get("Outcome")
            add_result(name, outcome)

    return results
